sys_script_include.script:
function GetIntegerValue(vValue)
{
	if (vValue === true)
	{
		return 1;
	}
	var vResult = parseInt(vValue);
	if (isNaN(vResult))
	{
		return 0;
	}
	return vResult;
}

function GetValue(vObject, vKey1, vKey2, vKey3, vKey4, vKey5, vKey6, vKey7, vKey8, vKey9, vKey10)
{
	if (vObject == undefined)
	{
		return null;
	}
	if (vKey1 == undefined)
	{
		return null;
	}
	if (IsArray(vKey1) == true)
	{
		if (vKey2 != null)
		{
			return null;
		}
		if (vKey1.length > 6)
		{
			return null;
		}
		return GetValue(
			vObject,
			GetValue(vKey1,0),
			GetValue(vKey1,1),
			GetValue(vKey1,2),
			GetValue(vKey1,3),
			GetValue(vKey1,4),
			GetValue(vKey1,5),
			GetValue(vKey1,6),
			GetValue(vKey1,7),
			GetValue(vKey1,8),
			GetValue(vKey1,9)
		);
	}
	if (vKey2 == undefined || vKey2 == null)
	{
		if (vObject[vKey1] == undefined)
		{
			return null;
		}
		var vValue = vObject[vKey1];
		if (GetType(vValue) == 'ScopedGlideElement')
		{
			vValue = GetStringValue(vValue);
		}
		return vValue;
	}
	return GetValue(vObject[vKey1],vKey2,vKey3,vKey4,vKey5,vKey6,vKey7,vKey8,vKey9,vKey10);
}

function Clone(vValue,bSortKeys)
{
	var strType = GetType(vValue);
	bSortKeys = GetBoolValue(bSortKeys);
	if (strType == 'ScopedGlideElement')
	{
		if (vValue.getDisplayValue() == '0')
		{
			return '0';
		}
		if (vValue.nil() == false)
		{
			return ''+vValue;
		}
		return vValue.getDisplayValue();
	}
	else if (GetType(vValue) == 'ScopedGlideRecord')
	{
		var oClone = {};
		var aKeys = GetKeys(vValue);
		if (bSortKeys == true)
		{
			aKeys = aKeys.sort();
		}
		for (var nKey = 0; nKey < aKeys.length; nKey++)
		{
			var strKey = aKeys[nKey];
			oClone[strKey] = vValue.getValue(strKey);
		}
		return oClone;
	}	
	else if (IsObject(vValue) == true)
	{
		var oClone = {};
		var aKeys = GetKeys(vValue);
		if (bSortKeys == true)
		{
			aKeys = aKeys.sort();
		}
		for (var nKey = 0; nKey < aKeys.length; nKey++)
		{
			var strKey = aKeys[nKey];
			oClone[strKey] = Clone(vValue[strKey]);
		}
		return oClone;
	}
	else if (IsArray(vValue) == true)
	{
		var aClone = [];
		for (var nIndex = 0; nIndex < vValue.length; nIndex++)
		{
			aClone.push(Clone(vValue[nIndex]));
		}
		return aClone;
	}	
	return vValue;
}

function BindAllFunctionsToThis(vValue)
{
	if (GetType(vValue) != 'Object')
	{
		return false;
	}
	var aFunctions = GetFunctions(vValue);
	for (var nFunction = 0; nFunction < aFunctions.length; nFunction++)
	{
		var strFunction = aFunctions[nFunction];
		vValue[strFunction] = vValue[strFunction].bind(vValue);
	}
	return true;
}

function RenderValueHex(vValue,strByteSeparator)
{
	if (vValue == null)
	{
		return '';
	}

	strByteSeparator = GetStringValue(strByteSeparator);

	var strType = GetType(vValue);
	if (strType == 'Array')
	{
		var strResult = '';
		for (var nPos = 0; nPos < vValue.length; nPos++)
		{
			if (nPos > 0)
			{
				strResult += strByteSeparator;	
			}
			strResult += RenderValueHex(vValue[nPos],strByteSeparator); 
		}
		return strResult;
	}	

	if (strType == 'string')
	{
		var strResult = '';
		for (var nPos = 0; nPos < vValue.length; nPos++)
		{
			if (nPos > 0)
			{
				strResult += strByteSeparator;	
			}
			strResult += RenderValueHex(vValue[nPos].charCodeAt(0),strByteSeparator); 
		}
		return strResult;
	}
	if (strType == 'number')
	{
		var num = Number(vValue);
		var strResult = num.toString(16);
		strResult = strResult.length % 2 ? '0' + strResult : strResult;

		var strResultNew = '';
		for (var nPos = 0; nPos < strResult.length; nPos += 2)
		{
			if (nPos > 0)
			{
				strResultNew += strByteSeparator;	
			}
			strResultNew += strResult[nPos] + strResult[nPos+1];
		}
		strResult = strResultNew.toUpperCase();
		return strResult;
	}
	return '';
}
